sys_script_include.script:
var GetStateFromLastForm = Class.create();
GetStateFromLastForm.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getStateFun: function() {
        var sys_id = this.getParameter('sysparm_sys_id');
        var gr = new GlideRecord('sc_req_item');
        if (gr.get(sys_id)) {
            gs.error('state=' + gr.state);
            gs.error('approval=' + gr.approval);
            if (gr.state == 12) {
                gs.error('return=' + '1');
                return '1';
            } else return '2';
        }
        return '';
    },
    type: 'GetStateFromLastForm'
});
